    : '01m3jtcb8gbayp46bznx5bn2cp';
}
if (Object.keys(cf).length > 0) {
  payload.custom_fields = cf;
}

const res = await requestCrm('/api/v1/people/' + contactId, 'PUT', payload);
if (!res.ok) {
  return JSON.stringify({ error: res.data?.message || 'Update failed', details: res.data?.errors });
}
return JSON.stringify({ success: true, updated_id: contactId, data: res.data?.data });

